//! Drives the `kpf` binary offline through an oracle-market lifecycle (docs/TESTNET.md, "Oracle-only market"): a
//! market block from a feed definition, the wallet's check (and its refusals), a slot, a stake, two orders, the open, a
//! vouched claim, watch, a contest, the resolution, finalize. Funding files list synthetic UTXOs (the builders and the
//! local verification need no chain); the DAA a node would report is written into each object file, as
//! `kpf status --update` does. Keys are generated by `kpf keygen` into a temporary directory outside any repository.
//! No node is contacted and nothing is submitted.

use std::path::PathBuf;
use std::process::Command;

use serde_json::{json, Value};

struct H {
    dir: PathBuf,
    n: usize,
}

impl Drop for H {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

fn bin() -> Command {
    Command::new(env!("CARGO_BIN_EXE_kpf"))
}

impl H {
    fn new() -> H {
        let dir = std::env::temp_dir().join(format!("kpf-oracle-cli-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        H { dir, n: 0 }
    }
    fn p(&self, name: &str) -> String {
        self.dir.join(name).display().to_string()
    }
    fn run(&self, args: &[&str]) -> (bool, String, String) {
        let o = bin().args(args).output().expect("run kpf");
        (o.status.success(), String::from_utf8_lossy(&o.stdout).into_owned(), String::from_utf8_lossy(&o.stderr).into_owned())
    }
    fn ok(&self, args: &[&str]) -> String {
        let (ok, out, err) = self.run(args);
        assert!(ok, "kpf {args:?} failed:\n{err}\n{out}");
        out
    }
    fn fail(&self, args: &[&str]) -> String {
        let (ok, out, err) = self.run(args);
        assert!(!ok, "kpf {args:?} should have failed:\n{out}");
        err
    }
    fn key(&self, name: &str) -> (String, String) {
        let path = self.p(&format!("{name}.key.json"));
        self.ok(&["keygen", "--out", &path]);
        let v: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        (path, v["publicKey"].as_str().unwrap().to_string())
    }
    /// A funding file of one synthetic UTXO of `kas` KAS.
    fn funding(&mut self, kas: u64) -> String {
        self.n += 1;
        let txid = format!("{:064x}", 0x5eed_0000u64 + self.n as u64);
        let path = self.p(&format!("funding-{}.json", self.n));
        std::fs::write(&path, serde_json::to_string(&json!([{ "txid": txid, "index": 0, "amount": kas * 100_000_000, "daa": 0 }])).unwrap()).unwrap();
        path
    }
    /// Runs a builder into a fresh out-dir and returns the object file whose kind contains `kind`, its DAA set to
    /// `daa`.
    fn step(&mut self, args: &[&str], kind: &str, daa: u64) -> String {
        self.n += 1;
        let out = self.p(&format!("out{}", self.n));
        let mut a: Vec<&str> = args.to_vec();
        a.extend(["--out-dir", &out]);
        let stdout = self.ok(&a);
        assert!(stdout.contains("not submitted"), "{stdout}");
        self.obj(&out, kind, daa)
    }
    fn obj(&self, out: &str, kind: &str, daa: u64) -> String {
        let f = std::fs::read_dir(out)
            .unwrap()
            .map(|e| e.unwrap().path())
            .find(|p| p.to_string_lossy().contains(&kind.replace(' ', "-")))
            .unwrap_or_else(|| panic!("no {kind} in {out}"));
        let mut v: Value = serde_json::from_str(&std::fs::read_to_string(&f).unwrap()).unwrap();
        v["daa"] = json!(daa);
        std::fs::write(&f, serde_json::to_string_pretty(&v).unwrap()).unwrap();
        f.display().to_string()
    }
}

const FEED: &str = "kpf feed definition v1\nquantity: example slow underlying, published once per hour\nunit: KAS per whole unit\nsources: median of three named public sources\ntime: the price at the DAA score t0, mapped to the accepting block's timestamp\nsessions: always open\ndisagreement: a claim is true if within 0.25 % of the median\n";

#[test]
fn oracle_market_lifecycle_from_the_command_line() {
    let mut h = H::new();
    let feed = h.p("feed.txt");
    std::fs::write(&feed, FEED).unwrap();
    let market = h.p("market.json");
    let out = h.ok(&["oracle-market", "--feed", &feed, "--out", &market]);
    assert!(out.contains("market id") && out.contains("not approved, listed or verified"), "{out}");
    assert!(!out.contains("WARNING"), "the testnet defaults raise no warning: {out}");
    // The wallet's check: the text matches, the worst case in words.
    let out = h.ok(&["oracle-check", "--market", &market, "--feed", &feed, "--size", "1000", "--x", "10", "--long-rate", "1", "--short-rate", "2", "--cover-rate", "6", "--premium", "0.02"]);
    assert!(out.contains("feed definition: hash matches") && out.contains("the long's margin 1000 KAS"), "{out}");
    // One byte of the feed text off: refused.
    let feed2 = h.p("feed2.txt");
    std::fs::write(&feed2, FEED.replace("0.25 %", "0.26 %")).unwrap();
    assert!(h.fail(&["oracle-check", "--market", &market, "--feed", &feed2]).contains("REFUSED"));
    // A misleading text with the right hash still raises warnings.
    let feed3 = h.p("feed3.txt");
    std::fs::write(&feed3, FEED.replace("example", "ex\u{200b}ample")).unwrap();
    let m3 = h.p("market3.json");
    h.ok(&["oracle-market", "--feed", &feed3, "--out", &m3]);
    assert!(h.ok(&["oracle-check", "--market", &m3, "--feed", &feed3]).contains("invisible character"));
    // A hostile block passes the bounds and is flagged; a block outside them is refused.
    let mh = h.p("hostile.json");
    let out = h.ok(&["oracle-market", "--feed", &feed, "--out", &mh, "--window-daa", "1", "--quiet-daa", "0", "--rho-bps", "50000"]);
    assert!(out.contains("WARNING: the contest window") && out.contains("WARNING: rho is 5"), "{out}");
    assert!(h.fail(&["oracle-market", "--feed", &feed, "--rho-bps", "50001"]).contains("bounds"));
    let mut v: Value = serde_json::from_str(&std::fs::read_to_string(&mh).unwrap()).unwrap();
    v["pair"]["gBps"] = json!(0);
    std::fs::write(&mh, serde_json::to_string(&v).unwrap()).unwrap();
    assert!(h.fail(&["oracle-check", "--market", &mh, "--feed", &feed]).contains("differ"));

    let (uw, uwk) = h.key("uw");
    let (lk, lkk) = h.key("long");
    let (sk, _) = h.key("short");
    let (st, _) = h.key("staker");
    let (ex, exk) = h.key("exec");
    let f = h.funding(30_100);
    let slot = h.step(&["bond", "--market", &market, "--value", "30000", "--funder", &uw, "--funding", &f, "--daa", "0"], "underwriting slot", 0);
    let f = h.funding(1_010);
    let stake = h.step(&["stake", "--market", &market, "--value", "100", "--funder", &st, "--funding", &f], "judge stake", 0);
    let f = h.funding(3_100);
    let lo = h.step(&["oracle-order", "--market", &market, "--side", "long", "--size", "2000", "--limit", "10.5", "--rate", "1", "--min-counter-rate", "1.5", "--expiry", "1000000000", "--prem-max", "0.1", "--escrow", "3000", "--funder", &lk, "--funding", &f], "oracle order", 1_000_000);
    let f = h.funding(5_100);
    let so = h.step(&["oracle-order", "--market", &market, "--side", "short", "--size", "2000", "--limit", "9.5", "--rate", "2", "--min-counter-rate", "0.5", "--expiry", "1000000000", "--prem-max", "0.1", "--escrow", "5000", "--funder", &sk, "--funding", &f], "oracle order", 1_000_000);
    let f = h.funding(10);
    let pair = h.step(&["oracle-open", "--long", &lo, "--short", &so, "--slot", &slot, "--n", "1000", "--x", "10", "--cover-rate", "6", "--premium", "0.02", "--key", &uw, "--funder", &ex, "--funding", &f, "--daa", "7000000"], "oracle pair", 7_000_000);
    let out = h.ok(&["oracle-watch", "--me", &lkk, "--object", &pair, "--daa", "7100000"]);
    assert!(out.contains("your underwriter's cover runs until DAA 27216000"), "{out}");
    // The underwriter vouches a liquidation of the long.
    let vouch = h.funding(700);
    let mut v: Value = serde_json::from_str(&std::fs::read_to_string(&vouch).unwrap()).unwrap();
    v[0]["scriptPublicKey"] = json!(format!("000020{uwk}ac"));
    std::fs::write(&vouch, serde_json::to_string(&v).unwrap()).unwrap();
    let f = h.funding(10);
    let pend = h.step(&["vouch", "--pair", &pair, "--kind", "liquidate", "--side", "long", "--price", "9.2", "--t0", "7999000", "--vouch", &vouch, "--key", &uw, "--funder", &ex, "--funding", &f, "--daa", "7999000"], "oracle pending part", 8_000_000);
    let out = h.ok(&["oracle-watch", "--me", &lkk, "--object", &pend, "--daa", "8100000"]);
    assert!(out.contains("A CLAIM AGAINST YOU") && out.contains("contest until DAA 8215999 (115999 DAA left)"), "{out}");
    // Review 6 (note 3): without a node the file's DAA is shown as unchecked.
    assert!(out.contains("[DAA from the object file, not checked against a node: pass --node]"), "{out}");
    // A stranger cannot vouch: the tool refuses a vouch input of another key.
    let f = h.funding(10);
    let mut v: Value = serde_json::from_str(&std::fs::read_to_string(&f).unwrap()).unwrap();
    v[0]["scriptPublicKey"] = json!(format!("000020{exk}ac"));
    std::fs::write(&f, serde_json::to_string(&v).unwrap()).unwrap();
    assert!(h.fail(&["vouch", "--pair", &pair, "--kind", "liquidate", "--side", "long", "--price", "9.2", "--vouch", &f, "--key", &uw, "--funder", &ex, "--funding", &f, "--daa", "7999000"]).contains("no plain UTXO of the pair's underwriter"));
    // The staker contests; the dispute resolves after its round; the verdict restores the part and pays the bond.
    let f = h.funding(10);
    h.n += 1;
    let out = h.p(&format!("out{}", h.n));
    // Review 7 (R7-F2): without a node a contest is refused unless the user accepts an untraced claim; with the claim's
    // birth transaction (the vouch's, written by the tool) the claim is traced to the pair's propose.
    let claim_tx = std::fs::read_dir(std::path::Path::new(&pend).parent().unwrap())
        .unwrap()
        .map(|e| e.unwrap().path())
        .find(|p| p.to_string_lossy().ends_with("-tx.json"))
        .expect("the vouch's transaction file")
        .display()
        .to_string();
    let err = h.fail(&["contest", "--pending", &pend, "--stake", &stake, "--key", &st, "--funder", &ex, "--funding", &f, "--daa", "8100000", "--out-dir", &out]);
    assert!(err.contains("refused without --node") && err.contains("--accept-untraced"), "{err}");
    let o = h.ok(&["contest", "--pending", &pend, "--stake", &stake, "--key", &st, "--funder", &ex, "--funding", &f, "--daa", "8100000", "--out-dir", &out, "--claim-tx", &claim_tx, "--accept-untraced"]);
    assert!(o.contains("traced: the claim was born alone") && o.contains("NOT CHECKED that the claim is live"), "{o}");
    let cw = h.obj(&out, "oracle pending part", 8_100_000);
    // Review 6 (note 2): a contested part whose contest landed after the window (its UTXO at P + W or later) is shown
    // as one whose verdict will be ignored.
    {
        let late = format!("{cw}.late.json");
        let mut v: Value = serde_json::from_str(&std::fs::read_to_string(&cw).unwrap()).unwrap();
        v["daa"] = json!(8_216_000);
        std::fs::write(&late, serde_json::to_string_pretty(&v).unwrap()).unwrap();
        let o = h.ok(&["oracle-watch", "--me", &lkk, "--object", &late, "--daa", "8216000"]);
        assert!(o.contains("after the window") && o.contains("the verdict will be ignored"), "{o}");
        let o = h.ok(&["oracle-watch", "--me", &lkk, "--object", &cw, "--daa", "8216000"]);
        assert!(!o.contains("after the window"), "{o}");
        std::fs::remove_file(&late).unwrap();
    }
    let dispute = {
        let files: Vec<PathBuf> = std::fs::read_dir(&out).unwrap().map(|e| e.unwrap().path()).filter(|p| p.to_string_lossy().contains("judge-stake")).collect();
        let d = files.iter().find(|p| std::fs::read_to_string(p).unwrap().contains("status: 7")).expect("the dispute").clone();
        let mut v: Value = serde_json::from_str(&std::fs::read_to_string(&d).unwrap()).unwrap();
        v["daa"] = json!(8_100_000);
        std::fs::write(&d, serde_json::to_string_pretty(&v).unwrap()).unwrap();
        d.display().to_string()
    };
    // Review 7 (R7-F2): a deposit is refused without a node unless the user accepts an untraced dispute; with the
    // opening (the contest's transaction file) and the claim's birth, the dispute is traced and the deposit builds and
    // verifies (nothing saved).
    {
        let opening = std::fs::read_dir(&out).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with("-tx.json")).unwrap().display().to_string();
        let f = h.funding(10);
        let err = h.fail(&["deposit", "--dispute", &dispute, "--side", "yes", "--stake", &stake, "--key", &st, "--funder", &ex, "--funding", &f]);
        assert!(err.contains("refused without --node") && err.contains("genesis keeps every stake"), "{err}");
        let err = h.fail(&["deposit", "--dispute", &dispute, "--side", "yes", "--stake", &stake, "--key", &st, "--funder", &ex, "--funding", &f, "--opening", &opening]);
        assert!(err.contains("both --opening and --claim-tx"), "{err}");
        let o = h.ok(&["deposit", "--dispute", &dispute, "--side", "yes", "--stake", &stake, "--key", &st, "--funder", &ex, "--funding", &f, "--opening", &opening, "--claim-tx", &claim_tx, "--accept-untraced", "--no-save"]);
        assert!(o.contains("traced: the dispute was opened on the claim born alone") && o.contains("NOT CHECKED that the dispute is live"), "{o}");
        // The claim's birth given as the opening: the trace fails and the command refuses.
        let err = h.fail(&["deposit", "--dispute", &dispute, "--side", "yes", "--stake", &stake, "--key", &st, "--funder", &ex, "--funding", &f, "--opening", &claim_tx, "--claim-tx", &claim_tx, "--accept-untraced"]);
        assert!(err.contains("the dispute's trace failed"), "{err}");
    }
    let f = h.funding(10);
    let decided = h.step(&["resolve", "--dispute", &dispute, "--pending", &cw, "--funder", &ex, "--funding", &f], "oracle pending part", 8_600_000);
    let f = h.funding(10);
    let restored = h.step(&["oracle-finalize", "--pending", &decided, "--funder", &ex, "--funding", &f], "oracle pair", 8_600_000);
    let out = h.ok(&["oracle-watch", "--me", &lkk, "--object", &restored, "--daa", "30300000"]);
    assert!(out.contains("THE COVER HAS LAPSED") && out.contains("lapse-settle"), "{out}");
}
